S=list(csv.DictReader(open('stations.csv')))
C=list(csv.DictReader(open('certificates.csv')))
sch=set((x['station'],x['round'],x['channel']) for x in csv.DictReader(open('schedule.csv')))
roster=[s['station'] for s in S if s['use']=='production' and int(s['first_day'])<=14<=int(s['last_day'])]
cut={'before':17,'after':26}
best={}
for c in C:
    r=c['round']
    if int(c['issued'])>cut[r] or int(c['received'])>cut[r]:continue
    k=(c['station'],r,c['channel']);v=(int(c['issued']),int(c['edition']))
    if k not in best or v>best[k][0]:best[k]=(v,c)
panel=[];tot={'before':[0,0],'after':[0,0]};fr={'before':[],'after':[]}
for s in sorted(roster):
    ks=[k for k in sch if k[0]==s]
    ok=ks and all(k in best and best[k][1]['action']=='certify' for k in ks) and all(any(k[1]==r for k in ks) for r in cut)
    if not ok:continue
    panel.append(s)
    for r in cut:
        p=d=0
        for k in ks:
            if k[1]==r:
                c=best[k][1];p+=int(c['passed']);d+=int(c['passed'])+int(c['failed'])+int(c['unreadable'])
        tot[r][0]+=p;tot[r][1]+=d;fr[r].append(p/d)
b=sum(fr['before'])/len(panel)*100;a=sum(fr['after'])/len(panel)*100
import json
o=dict(roster_count=len(roster),paired_count=len(panel),panel=','.join(panel),before_pass=tot['before'][0],before_den=tot['before'][1],after_pass=tot['after'][0],after_den=tot['after'][1],before_pct=round(b,3),after_pct=round(a,3),change_pp=round(a-b,3),relative_change_pct=round((a-b)/b*100,3))
json.dump(o,open('answer.json','w'));print(o)

import csv, json
from pathlib import Path
read=lambda f:list(csv.DictReader(open(f,newline='')))
stations=read('stations.csv'); schedule=read('schedule.csv'); certs=read('certificates.csv')
roster=sorted({s['station'] for s in stations if s['use']=='production' and int(s['first_day'])<=9<=int(s['last_day'])})
print('roster',len(roster),roster)
# only listed schedule pairs for each station/round; select latest available release by issue, edition
selected={}
for c in certs:
 if int(c['issued'])<=22 and int(c['received'])<=22:
  key=(c['station'],c['round'],c['channel'])
  rank=(int(c['issued']),float(c['edition']))
  if key not in selected or rank>selected[key][0]: selected[key]=(rank,c)
# panel stations with an active selected cert for every scheduled station-channel in both rounds
required={s['station']:[] for s in schedule}
for r in schedule: required[r['station']].append((r['round'],r['channel']))
paired=[]
for station in roster:
 req=required.get(station,[])
 if all((station,rd,ch) in selected and selected[(station,rd,ch)][1]['action']=='certify' for rd,ch in req): paired.append(station)
print('paired',len(paired),paired)
# sum counts by round, across scheduled channels (use unique scheduled tuples)
counts={rd:[0,0] for rd in ['before','after']}
for station in paired:
 for r in schedule:
  if r['station']!=station: continue
  c=selected[(station,r['round'],r['channel'])][1]
  counts[r['round']][0]+=int(c['passed']); counts[r['round']][1]+=int(c['passed'])+int(c['failed'])
print('counts',counts)
bp,bd=counts['before']; ap,ad=counts['after']
bpct=100*bp/bd; apct=100*ap/ad
out={'roster_count':len(roster),'paired_count':len(paired),'panel':','.join(paired),'before_pass':bp,'before_den':bd,'after_pass':ap,'after_den':ad,'before_pct':round(bpct,3),'after_pct':round(apct,3),'change_pp':round(apct-bpct,3),'relative_change_pct':round((apct-bpct)/bpct*100,3)}
print(out)
Path('answer.json').write_text(json.dumps(out,separators=(',',':'))+'\n')
print(Path('answer.json').read_text())

