need={}
for s in sch:need.setdefault((s['station'],s['round']),set()).add(s['channel'])
cut={'before':21,'after':29};best={}
for r in ce:
    if int(r['issued'])>cut[r['round']] or int(r['received'])>cut[r['round']]:continue
    k=(r['station'],r['round'],r['channel']);p=(int(r['issued']),int(r['edition']))
    if k not in best or p>best[k][0]:best[k]=(p,r)
