bp,bd=tot['before'];ap,ad=tot['after']
b=100*bp/bd;a=100*ap/ad
import json
o=dict(roster_count=len(roster),paired_count=len(panel),panel=','.join(panel),before_pass=bp,before_den=bd,after_pass=ap,after_den=ad,before_pct=round(b,3),after_pct=round(a,3),change_pp=round(a-b,3),relative_change_pct=round((a-b)/b*100,3))
