R=lambda f:list(csv.DictReader(open(f+'.csv')))
st=[s['station'] for s in R('stations') if s['use']=='production' and int(s['first_day'])<=17<=int(s['last_day'])]
sch=collections.defaultdict(set)
for x in R('schedule'):sch[(x['station'],x['round'])].add(x['channel'])
