    if int(c['issued'])<=cut[c['round']] and int(c['received'])<=cut[c['round']]:
        k=(c['station'],c['round'],c['channel']);v=(int(c['issued']),int(c['edition']))
        if k not in best or v>best[k][0]:best[k]=(v,c)
panel=[];tot=collections.Counter()
for s in st:
