import csv, asof, json, math
from collections import defaultdict
stations=list(csv.DictReader(open('stations.csv',newline='')))
eligible=sorted(x['station'] for x in stations if x['use']=='production' and int(x['first_day'])<=9<=int(x['last_day']))
schedule=list(csv.DictReader(open('schedule.csv',newline='')))
# scheduled keys only relevant channels; derive each station's needed channel set per both rounds
sched=defaultdict(set)
for row in schedule:
 if row['channel'] in {'low','high','span'}: sched[(row['station'],row['round'])].add(row['channel'])
# independently select releases by cutoff, ranking issued then edition; ensure received and issued <= cutoff
rows=list(csv.DictReader(open('certificates.csv',newline='')))
selected={}
for rnd in ['before','after']:
 for r in rows:
  if r['round']!=rnd: continue
  if int(r['issued'])<=22 and int(r['received'])<=22:
   k=(r['station'],r['round'],r['channel'])
   rank=(int(r['issued']),int(r['edition']))
   if k not in selected or rank>selected[k][0]: selected[k]=(rank,r)
# identify each eligible's all channels in each round active
active={k:v[1] for k,v in selected.items() if v[1]['action']=='certify'}
paired=[]
for st in eligible:
 ok=True
 for rnd in ['before','after']:
  for ch in sched.get((st,rnd),set()):
   if (st,rnd,ch) not in active: ok=False
 if ok: paired.append(st)
print('eligible',eligible,'n=',len(eligible))
print('scheduled keys',len(sched))
print('paired',paired)
# inspect revised keys / excluded from paired channels status
for key in [('E06','before','span'),('E08','after','high'),('E27','after','low'),('E26','after','high'),('E09','after','low')]:
 print(key, selected.get(key,('unavailable',None))[1])
# counts among paired stations, scheduled channels only
sums={rnd:[0,0] for rnd in ['before','after']}
for st in paired:
 for rnd in ['before','after']:
  for ch in sched[(st,rnd)]:
   r=active[(st,rnd,ch)]
   sums[rnd][0]+=int(r['passed']); sums[rnd][1]+=int(r['passed'])+int(r['failed'])
print('sums',sums)
bp,bd=sums['before']; ap,ad=sums['after']
bpct=bp/bd*100; apct=ap/ad*100
out={'roster_count':len(eligible),'paired_count':len(paired),'panel':','.join(paired),'before_pass':bp,'before_den':bd,'after_pass':ap,'after_den':ad,'before_pct':round(bpct,3),'after_pct':round(apct,3),'change_pp':round(apct-bpct,3),'relative_change_pct':round((apct-bpct)/bpct*100,3)}
print(out)
open('answer.json','w').write(json.dumps(out,separators=(',',':'))+'\n')
