import csv, json, os
from collections import defaultdict
with open('stations.csv',newline='') as f: stations=list(csv.DictReader(f))
with open('schedule.csv',newline='') as f: sched=list(csv.DictReader(f))
with open('certificates.csv',newline='') as f: cert=list(csv.DictReader(f))
roster=sorted(r['station'] for r in stations if r['use']=='production' and int(r['first_day'])<=14<=int(r['last_day']))
cut={'before':17,'after':26}
selected={}
for row in cert:
    r=row['round']
    if int(row['issued'])>cut[r] or int(row['received'])>cut[r]: continue
    key=(row['station'],r,row['channel'])
    rank=(int(row['issued']),int(row['edition']))
    if key not in selected or rank>selected[key][0]: selected[key]=(rank,row)
channels=defaultdict(set)
for row in sched: channels[(row['station'],row['round'])].add(row['channel'])
panel=[]
for st in roster:
    ok=True
    for rnd in ('before','after'):
        for ch in channels[(st,rnd)]:
            v=selected.get((st,rnd,ch))
            if not v or v[1]['action']!='certify': ok=False
    if ok: panel.append(st)
print('roster',len(roster),roster)
print('panel',len(panel),panel)
pooled={}
means={}
for rnd in ('before','after'):
    p=d=0; fr=[]
    for st in panel:
        sp=sd=0
        for ch in channels[(st,rnd)]:
            row=selected[(st,rnd,ch)][1]
            passed=int(row['passed']); den=passed+int(row['failed'])+int(row['unreadable'])
            sp+=passed; sd+=den
        p+=sp; d+=sd; fr.append(sp/sd)
    pooled[rnd]=(p,d); means[rnd]=sum(fr)/len(fr)
b=means['before']; a=means['after'];
result={'roster_count':len(roster),'paired_count':len(panel),'panel':','.join(panel),'before_pass':pooled['before'][0],'before_den':pooled['before'][1],'after_pass':pooled['after'][0],'after_den':pooled['after'][1],'before_pct':round(b*100,3),'after_pct':round(a*100,3),'change_pp':round((a-b)*100,3),'relative_change_pct':round((a-b)/b*100,3)}
print('means fractions',means)
print(result)
with open('answer.json','w') as f: json.dump(result,f,separators=(',',':'))
print('written',open('answer.json').read())

